   /**
    * f0 -> <IDENTIFIER>
    */
   public R visit(Identifier n, A argu) {
      R _ret=null;
      if(in_main||in_fun_type){
         return _ret;
      }
      n.f0.accept(this, argu);
      String temp = n.f0.toString();
      // System.out.println(temp);
      if(in_class_decl||in_msg_call_fun){
         return (R)temp;
      }
      if(in_msg_class_call){
      // System.out.println(currtype + "  A");
         Functioninfo currfuninfo = classesmapinfo.get(currclassname).class_funcinfo.get(currmthd_label);
         Classinfo currclassinfo = classesmapinfo.get(currclassname);
         if(currfuninfo.param_no_map.containsKey(temp)){
            // System.out.println("y1");
            int idx = currfuninfo.param_no_map.get(temp);
            // System.out.println(idx+ "pp");
            // for(int i =0 ;i< currfuninfo.func_paramname.size();i++){
            //    System.out.println(currfuninfo.func_paramname.elementAt(i));
            // }
            // for(int i =0 ;i< currfuninfo.func_paramtype.size();i++){
            //    System.out.println(currfuninfo.func_paramtype.elementAt(i));
            // }
            currtype = currfuninfo.func_paramtype.elementAt(idx-1);
         }else{
            if(currfuninfo.func_varinfo.containsKey(temp)){
            // System.out.println("y2");
               currtype = currfuninfo.func_varinfo.get(temp).type;
            }else{
            // System.out.println("y3");
               currtype = currclassinfo.class_varinfo.get(temp).type;
            }
         }
         // System.out.println(temp + "lm kmc");
      // System.out.println(currtype + "   B");

      }
      // if(!classesmapinfo.get(currclassname).class_funcinfo.containsKey(currmthd_label)){
         // System.out.println(currclassname+ " ooo " + currmthd_label);
         // System.exit(0);
      // }
      // if(!classesmapinfo.containsKey(currclassname)){
      //        System.out.println(currclassname+ " ooo ");
      //    System.exit(0);
      // }
      if(currclassname==null){
         return null;
      }
      Map<String,Integer> m = classesmapinfo.get(currclassname).class_funcinfo.get(currmthd_label).param_no_map;
      if(m.containsKey(temp)){
         int param_no = m.get(temp);
         _ret = (R)("TEMP  " + Integer.toString(param_no));
      }else{
          Map<String,Integer> m1 = classesmapinfo.get(currclassname).class_funcinfo.get(currmthd_label).var_temp_no_map;
          if(m1.containsKey(temp)){
            int param_no = m1.get(temp);
            _ret = (R)("TEMP  " + Integer.toString(param_no));
          }else{
            // if(!classesmapinfo.get(currclassname).offset_map_var.containsKey(temp)){
            //    System.out.println("seeeee " + currclassname + " " + currmthd_label + " " + temp );
            //    System.exit(0);
            // }
            int var_offset = classesmapinfo.get(currclassname).offset_map_var.get(temp);
            int present_temp_count = classesmapinfo.get(currclassname).class_funcinfo.get(currmthd_label).total_temp_count;
            if(in_lhs_assign){
               class_var = true;
               _ret = (R)("HSTORE  TEMP 0  " + Integer.toString(var_offset) + "  ");
            }else{
               classesmapinfo.get(currclassname).class_funcinfo.get(currmthd_label).total_temp_count++;
              _ret = (R)("\nBEGIN \n\nHLOAD TEMP " + Integer.toString(present_temp_count) + "  TEMP 0  " + Integer.toString(var_offset) + "\nRETURN   TEMP  " + Integer.toString(present_temp_count) +"  \n\nEND\n" );
            }
          }
      }
      return _ret;
   }

